import { useState, useEffect } from "react";
import { Col, Container, Row } from "react-bootstrap";
import { useDispatch } from "react-redux";
import { toast } from "react-toastify";
import { useAuth } from "../../hooks/useAuth";
import { useVersion } from "../../pages/VersionContext";
import { addToCart } from "../../app/features/cart/cartSlice";
import "./product-details.css";
import { ENDPOINTS } from '../../app/config/config.js';

const ProductDetails = ({ selectedProduct }) => {
  const [isGamified, setIsGamified] = useState(() => {
    const version = localStorage.getItem('appVersion');
    return version === 'gamification';
});
  const { isAuthenticated, user } = useAuth();
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [averageRating, setAverageRating] = useState(0);

  const [userReview, setUserReview] = useState("");
  const [userRating, setUserRating] = useState(0);


  const fetchReviews = async () => {
    console.log(isGamified)
    try {
      const response = await fetch(`${ENDPOINTS.CommentReview}/getReviews/${selectedProduct.productName}`);
      if (!response.ok) throw new Error('Failed to fetch reviews');
      const data = await response.json();
      setReviews(data);
      if (data.length > 0) {
        const total = data.reduce((sum, review) => sum + review.rating, 0);
        setAverageRating(total / data.length);
      } else {
        setAverageRating(0);
      }
    } catch (error) {
      toast.error("Failed to load reviews");
    } finally {
      setLoading(false);
    }
  };

    // Star rating display component
    const StarRating = ({ rating, totalReviews }) => (
      <div className="average-rating">
        <div className="stars">
          {[1, 2, 3, 4, 5].map((star) => (
            <span
              key={star}
              className={`star ${star <= rating ? 'filled' : ''}`}
            >
              ★
            </span>
          ))}
        </div>
        {totalReviews > 0 && (
          <span className="rating-stats">
            {rating.toFixed(1)} out of 5 ({totalReviews} {totalReviews === 1 ? 'review' : 'reviews'})
          </span>
        )}
      </div>
    );

  // This will run once when the component mounts
  useEffect(() => {
    fetchReviews();
  }, []); //
  const handleSubmitReview = async () => {
    if (!userRating) {
      toast.error("Please select a rating");
      return;
    }

    try {
      const response = await fetch(`${ENDPOINTS.CommentReview}/sendReview`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${user.token}`
        },
        body: JSON.stringify({
          productname: selectedProduct.productName,
          username: user.username,
          comment:userReview,
          rating: userRating
        })
      });

      if (!response.ok) throw new Error('Failed to submit review');
      
      toast.success("Review submitted successfully!");
      setUserReview("");
      setUserRating(0);
      fetchReviews(); // Refresh reviews
    } catch (error) {
      toast.error("Failed to submit review");
    }
  };

  return (
    <section className="product-page">
      <Container>
        <Row className="justify-content-center">
          {/* Existing product details code */}
          <Col md={6}>
            <img loading="lazy" src={selectedProduct?.imgUrl} alt="" />
          </Col>
          <Col md={6}>
            <h2>{selectedProduct?.productName}</h2>
            {/* ... other product details ... */}
          </Col>
        </Row>

        {/* Reviews Section - Only show in gamified version */}
        {isGamified && (
          <Row className="reviews-section mt-5">
            <Col md={12}>
              <h3>Reviews</h3>

                            {/* Average Rating Display */}
                            {!loading && (
                <div className="rating-summary">
                  <StarRating 
                    rating={averageRating} 
                    totalReviews={reviews.length}
                  />
                </div>
              )}
              
              {/* Review Form - Only show if authenticated */}
              {isAuthenticated && (
                <div className="review-form">
                  <h4>Write a Review</h4>
                  <div className="rating-input">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <span
                        key={star}
                        onClick={() => setUserRating(star)}
                        className={`star ${userRating >= star ? 'filled' : ''}`}
                      >
                        ★
                      </span>
                    ))}
                  </div>
                  <textarea
                    value={userReview}
                    onChange={(e) => setUserReview(e.target.value)}
                    placeholder="Write your review here..."
                    rows="4"
                    className="review-textarea"
                  />
                  <button 
                    className="submit-review-btn"
                    onClick={handleSubmitReview}
                  >
                    Submit Review
                  </button>
                </div>
              )}

              {/* Reviews List */}
              {loading ? (
                <div>Loading reviews...</div>
              ) : (
                <div className="reviews-list">
                  {reviews.map((review) => (
                    <div key={review.id} className="review-item">
                      <div className="review-header">
                        <span className="reviewer-name">{review.username}</span>
                        <div className="review-rating">
                          {[...Array(5)].map((_, index) => (
                            <span key={index} className={`star ${index < review.rating ? 'filled' : ''}`}>
                              ★
                            </span>
                          ))}
                        </div>
                      </div>
                      <p className="review-text">{review.review}</p>
                      <span className="review-date">
                        {new Date(review.created_at).toLocaleDateString()}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </Col>
          </Row>
        )}
      </Container>
    </section>
  );
};

export default ProductDetails;
